-- A hidden "sandbox" competition for testing on production data, e.g. the
-- Gold/Silver generator (src/groups.ts), at sandbox.isail.site or
-- http://sandbox.localhost:<port>. It's hidden from the landing page and the
-- competition picker (see `hidden` in src/competitions.ts).
--
-- Its qualifying races are a copy of Sixpack's 78 qualifying races on
-- 2026-11-21 (same numbers, flights and teams), inserted as new rows, with
-- made-up results: each race's positions are a permutation of 1-6, split 3
-- and 3, so the standings are complete. Applied to production on 2026-11-21.
-- Rerunning it resets the sandbox: it only deletes and inserts sandbox rows.
BEGIN;

INSERT INTO public.competition
  (id, name, host, stage, racing_paused, estimates, go_to_stand, feedback)
VALUES
  ('sandbox', 'Sandbox', 'sandbox.isail.site', 'quali', false, true, 2, false)
ON CONFLICT (id) DO UPDATE SET stage = 'quali';

INSERT INTO public.admin (competition, "user")
SELECT 'sandbox', u.id FROM auth.users u WHERE u.email = 'charlie.lidbury@icloud.com'
ON CONFLICT DO NOTHING;

DELETE FROM public.race WHERE competition = 'sandbox';

